mapper.select:
select 
from sys_role
where name = #{name}
  and tenant_id = #{tenantId}
  and delete_flag = 1
limit 1

mapper.update:
update  sys_role
set  updated_by = #{updatedBy}, updated_dt = #{updatedDt}

    ,name = #{name}


    ,data_scope = #{dataScope}


    ,status = #{status}


    ,menu_check_strictly = #{menuCheckStrictly}

where id = #{id}

update  sys_role
set delete_flag = -1, updated_by = #{updatedBy}, updated_dt = #{updatedDt}
where id = #{id}
